  wc_wash(q,wc_rect(168,70,52,52),[226,232,238],{kind:"thing",lw:1.3,seed:5});wc_wash(q,wc_ell(222,94,11,15,14),[226,232,238],{kind:"thing",lw:1.3,seed:6});
